yesterday_sales = 250000
today_sales = 275000
total_sales = yesterday_sales + today_sales
print(f"total sales: {total_sales}")
sales_target = 200000
print(f"sales target 200000: {sales_target}")
weekly_sales_target = 200000*7
print(f"weekly sales target: {weekly_sales_target}")
daily_average_sales = total_sales / 2
print(f"daily average sales: {daily_average_sales}")
daily_sales_avarage = total_sales // 2
print(f"daily sales avarage: {daily_sales_avarage}")
print(f"daily sales avarage to power of 2: {daily_sales_avarage ** 2}")